// runCLI executes one goalforge invocation through the real dispatch and
// returns its stdout, failing the test on error.
func runCLI(t *testing.T, ctx context.Context, args ...string) string {
	t.Helper()
	output, err := runCLIWithError(t, ctx, args...)
	if err != nil {
		t.Fatalf("goalforge %v: %v\noutput:\n%s", args, err, output)
	}
	return output
}

func runCLIWithError(t *testing.T, ctx context.Context, args ...string) (string, error) {
	t.Helper()
	previous := os.Stdout
	read, write, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	os.Stdout = write
	runErr := run(ctx, args)
	_ = write.Close()
	os.Stdout = previous
	output, _ := io.ReadAll(read)
	return string(output), runErr
}

func gitIn(t *testing.T, dir string, args ...string) string {
	t.Helper()
	cmd := exec.Command("git", append([]string{"-C", dir}, args...)...)
	output, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %v: %v: %s", args, err, output)
	}
	return strings.TrimSpace(string(output))
}

// requirePushable establishes with plain git — no GoalForge code in the path —
// that this environment can publish to the bare repository the test just
// created. A sandbox that blocks pushing is an environment limit, not a
// regression, and reporting it as one buries the real failures underneath it.
// Only plain git is exempted, never the code under test: wherever pushing works
// (CI included) the test runs in full and still catches push regressions. The
// probe goes through the same remote name the test uses, because pushing can be
// disabled per remote rather than outright.
func requirePushable(t *testing.T, repository, remote string) {
	t.Helper()
	const probe = "refs/heads/goalforge-push-probe"
	output, err := exec.Command("git", "-C", repository, "push", remote, "HEAD:"+probe).CombinedOutput()
	if err != nil {
		t.Skipf("environment cannot push to its own bare repository via %q: %v: %s",
			remote, err, strings.TrimSpace(string(output)))
	}
	_ = exec.Command("git", "-C", repository, "push", remote, ":"+probe).Run()
}

// TestCLIFullLifecycle drives the complete user journey through the real CLI
func (s *Server) goalSet(ctx context.Context, args toolArgs) (string, error) {
	project, err := s.resolveProject(ctx, args.Project)
	if err != nil {
		return "", err
	}
	if args.Title == "" || args.Objective == "" {
		return "", errors.New("title and objective are required")
	}
	criteria := make([]model.Criterion, 0, len(args.Criteria))
	for _, raw := range args.Criteria {
		criterion, parseErr := model.ParseCriterion(raw)
		if parseErr != nil {
			return "", parseErr
		}
		criteria = append(criteria, criterion)
	}
	return marshal(s.store.SetGoal(ctx, project.ID, args.Title, args.Objective, args.Reason, criteria))
}

func (s *Server) workList(ctx context.Context, args toolArgs) (string, error) {
	project, err := s.resolveProject(ctx, args.Project)
	if err != nil {
		return "", err
	}
	goal, err := s.currentGoal(ctx, project.ID)
	if err != nil {
		return "", err
	}
	items, err := s.store.ListWorkItems(ctx, goal.ID)
	if err != nil {
		return "", err
	}
	scores, err := s.store.IdeaScoresForGoal(ctx, goal.ID)
	if err != nil {
		return "", err
	}
	type view struct {
		model.WorkItem
		Score *model.IdeaScore `json:",omitempty"`
	}
	result := make([]view, 0, len(items))
	for _, item := range items {
		entry := view{WorkItem: item}
		if score, ok := scores[item.ID]; ok {
			entry.Score = &score
		}
		result = append(result, entry)
	}
	return marshal(result, nil)
}
